def _leer_universo(universo_path: Path) -> list[str]:
    """Lee el archivo de universo, omitiendo líneas vacías."""
    texto = Path(universo_path).read_text(encoding="utf-8")
    return [linea.strip() for linea in texto.splitlines() if linea.strip()]


def _leer_parquet(ruta: Path) -> pd.DataFrame | None:
    """Carga un parquet de precios; devuelve None si el archivo no existe."""
    ruta = Path(ruta)
    if not ruta.exists():
        return None

    df = pd.read_parquet(ruta)
    if not isinstance(df.index, pd.DatetimeIndex):
        try:
            df.index = pd.to_datetime(df.index)
        except Exception:
            pass
    return df.sort_index()


def _ajustar_ohlc_seguro(df: pd.DataFrame) -> pd.DataFrame:
    """Aplica ``exp005.ajustar_ohlc`` manteniendo un DataFrame OHLCV."""
    copia = df.copy()

    try:
        ajustado = ajustar_ohlc(copia)
    except Exception:
        try:
            ajustado = ajustar_ohlc(df)
        except Exception:
            ajustado = df

    if isinstance(ajustado, tuple):
        ajustado = ajustado[0] if ajustado else None

    if ajustado is None:
        return copia

    if isinstance(ajustado, pd.Series):
        copia["close"] = ajustado.reindex(copia.index)
        return copia

    if isinstance(ajustado, np.ndarray):
        copia["close"] = pd.Series(ajustado, index=copia.index)
        return copia

    if isinstance(ajustado, pd.DataFrame):
        # Si la función de ajuste devolviera sólo algunas columnas, conservamos
        # las columnas OHLCV originales que falten.
        for columna in df.columns:
            if columna not in ajustado.columns:
                ajustado[columna] = df[columna]
        return ajustado.sort_index()

    return copia


def _serie_cierre(ajustado: Any) -> pd.Series:
    """Extrae la serie de cierre ajustado de un DataFrame o Series."""
    if isinstance(ajustado, pd.Series):
        return ajustado.sort_index()

    if isinstance(ajustado, pd.DataFrame):
        for columna in ("close_ajustado", "close_adj", "adj_close", "close"):
            if columna in ajustado.columns:
                serie = ajustado[columna]
                if isinstance(serie, pd.DataFrame):
                    serie = serie.iloc[:, 0]
                return serie.sort_index()

    raise ValueError("No se pudo encontrar una columna de cierre en los datos ajustados")


def _calcular_features_seguro(df_ajustado: Any) -> pd.DataFrame:
    """Calcula las features de un símbolo con compatibilidad de firma."""
    funcion = features.calcular_features_simbolo

    candidatos: list[tuple[Any, ...]] = [(df_ajustado,)]

    if isinstance(df_ajustado, pd.DataFrame):
        if "close" in df_ajustado.columns:
            candidatos.append((df_ajustado["close"],))
            if "volume" in df_ajustado.columns:
                candidatos.append((df_ajustado["close"], df_ajustado["volume"]))

    primer_resultado: Any = None

    for args in candidatos:
        try:
            resultado = funcion(*args)
        except Exception:
            continue

        if resultado is None:
            # Algunas implementaciones mutan y no devuelven nada.
            if isinstance(args[0], pd.DataFrame):
                return args[0].sort_index()
            continue

        if isinstance(resultado, pd.DataFrame):
            return resultado.sort_index()

        if primer_resultado is None:
            primer_resultado = resultado

    if isinstance(primer_resultado, pd.DataFrame):
        return primer_resultado.sort_index()

    if isinstance(primer_resultado, pd.Series):
        return primer_resultado.to_frame().sort_index()

    # Último intento para propagar el error real si nada funcionó.
    resultado = funcion(df_ajustado)
    if isinstance(resultado, pd.DataFrame):
        return resultado.sort_index()
    if isinstance(resultado, pd.Series):
        return resultado.to_frame().sort_index()

    raise TypeError("calcular_features_simbolo no devolvió un DataFrame")


def _columnas_numericas(tabla: pd.DataFrame) -> list[str]:
    return [
        columna
        for columna in tabla.columns
        if pd.api.types.is_numeric_dtype(tabla[columna])
    ]


def _normalizar_seguro(tabla_cruda: pd.DataFrame) -> pd.DataFrame:
    """Normaliza percentiles cross-sectionales con compatibilidad de firma."""
    funcion = features.normalizar_percentil_cross_sectional
    columnas = _columnas_numericas(tabla_cruda)

    tabla_reset = tabla_cruda.reset_index()
    if "index" in tabla_reset.columns:
        tabla_reset = tabla_reset.rename(columns={"index": "ticker"})
    else:
        primera_columna = tabla_reset.columns[0]
        if primera_columna not in tabla_cruda.columns:
            tabla_reset = tabla_reset.rename(columns={primera_columna: "ticker"})

    candidatos: list[tuple[Any, ...]] = [
        (tabla_cruda,),
        (tabla_cruda.copy(), columnas),
        (tabla_reset,),
        (tabla_reset, columnas),
    ]

    primer_resultado: Any = None

    for args in candidatos:
        try:
            resultado = funcion(*args)
        except Exception:
            continue

        if resultado is None:
            resultado = args[0]

        if isinstance(resultado, pd.Series):
            resultado = resultado.to_frame()

        if isinstance(resultado, pd.DataFrame):
            if primer_resultado is None:
                primer_resultado = resultado
            if "ticker" in resultado.columns:
                resultado = resultado.set_index("ticker")
            elif "simbolo" in resultado.columns:
                resultado = resultado.set_index("simbolo")
            return resultado

    if isinstance(primer_resultado, pd.DataFrame):
        if "ticker" in primer_resultado.columns:
            return primer_resultado.set_index("ticker")
        return primer_resultado

    # Fallback determinista por si la función no estuviera disponible con las
    # firmas probadas.
    return tabla_cruda.rank(pct=True, method="average")


def _resultado_vacio(resultado: Any) -> bool:
    if resultado is None:
        return True

    if isinstance(resultado, pd.DataFrame):
        return resultado.empty

    if isinstance(resultado, pd.Series):
        if resultado.empty:
            return True
        if resultado.dtype == bool:
            return not bool(resultado.any())
        return False

    if isinstance(resultado, (list, tuple, set, dict, np.ndarray, pd.Index)):
        return len(resultado) == 0

    if isinstance(resultado, str):
        return False

    return False


def _llamar_seleccion(funcion: Any, candidatos: Sequence[tuple[Any, ...]]) -> Any:
    """Prueba varias firmas y prefiere el primer resultado no vacío."""
    primer_resultado: Any = None

    for args in candidatos:
        try:
            resultado = funcion(*args)
        except Exception:
            continue

        if primer_resultado is None:
            primer_resultado = resultado

        if not _resultado_vacio(resultado):
            return resultado

    return primer_resultado


def _extraer_tickers(resultado: Any, tabla: pd.DataFrame) -> list[str]:
    """Convierte el resultado variable de un baseline/bucket en tickers."""
    if resultado is None:
        return []

    if isinstance(resultado, pd.Timestamp):
        return []

    if isinstance(resultado, pd.DataFrame):
        if resultado.empty:
            return []
        if "ticker" in resultado.columns:
            valores = resultado["ticker"].tolist()
        elif "simbolo" in resultado.columns:
            valores = resultado["simbolo"].tolist()
        else:
            valores = resultado.index.tolist()
        return [str(v) for v in valores if pd.notna(v)]

    if isinstance(resultado, pd.Series):
        if resultado.empty:
            return []

        valores_no_nulos = resultado.dropna()
        if resultado.dtype == bool:
            return [str(v) for v in resultado.index[resultado.astype(bool)].tolist()]

        if len(valores_no_nulos) > 0 and all(
            isinstance(v, (bool, np.bool_)) for v in valores_no_nulos.tolist()
        ):
            mascara = resultado.fillna(False).astype(bool)
            return [str(v) for v in resultado.index[mascara].tolist()]

        valores = valores_no_nulos.tolist()
        if valores and all(isinstance(v, str) for v in valores):
            return [str(v) for v in valores]

        if resultado.name is not None and str(resultado.name) in set(map(str, tabla.index)):
            return [str(resultado.name)]

        return [str(v) for v in resultado.index.tolist()]

    if isinstance(resultado, pd.Index):
        return [str(v) for v in resultado.tolist()]

    if isinstance(resultado, np.ndarray):
        if resultado.dtype == bool and len(resultado) == len(tabla):
            return [str(v) for v in tabla.index[resultado].tolist()]
        return [str(v) for v in resultado.tolist()]

    if isinstance(resultado, dict):
        if "ticker" in resultado:
            return [str(resultado["ticker"])]
        if "simbolo" in resultado:
            return [str(resultado["simbolo"])]

        if resultado and all(
            isinstance(v, (bool, np.bool_)) for v in resultado.values()
        ):
            return [str(k) for k, v in resultado.items() if v]

        return [str(v) for v in resultado.values() if isinstance(v, str)]

    if isinstance(resultado, tuple):
        if (
            len(resultado) == 2
            and isinstance(resultado[0], str)
            and isinstance(resultado[1], (int, float, np.number))
        ):
            return [resultado[0]]
        return [str(v) for v in resultado if not isinstance(v, (int, float, np.number))]

    if isinstance(resultado, str):
        return [resultado]

    if isinstance(resultado, (list, set)):
        if (
            len(resultado) == len(tabla)
            and len(resultado) > 0
            and all(isinstance(v, (bool, np.bool_)) for v in resultado)
        ):
            return [str(v) for v in tabla.index[np.asarray(resultado, dtype=bool)].tolist()]
        if isinstance(resultado, set):
            return sorted(str(v) for v in resultado)
        return [str(v) for v in resultado]

    if isinstance(resultado, (int, float, np.number)):
        return []

    return []


def _aplicar_bucket_manual(tabla_norm: pd.DataFrame, bucket: dict) -> pd.Index:
    """Fallback determinista si ``grid.aplicar_bucket`` no fuese invocable."""
    umbrales = bucket.get("umbrales", {}) if isinstance(bucket, dict) else {}
    mascara = pd.Series(True, index=tabla_norm.index)

    for columna, regla in umbrales.items():
        if columna not in tabla_norm.columns:
            continue
        if not isinstance(regla, dict):
            continue

        percentil = float(regla.get("percentil", regla.get("umbral", 0.0)))
        direccion = str(regla.get("direccion", "alto")).lower()

        if direccion in {"alto", "high", "mayor"}:
            mascara &= tabla_norm[columna] >= percentil
        elif direccion in {"bajo", "low", "menor"}:
            mascara &= tabla_norm[columna] <= percentil

    return tabla_norm.index[mascara]


def _seleccionar_bucket(
    tabla_norm: pd.DataFrame,
    tabla_cruda: pd.DataFrame,
    bucket: dict,
) -> Any:
    """Aplica ``grid.aplicar_bucket`` probando las firmas habituales."""
    funcion = grid.aplicar_bucket
    umbrales = bucket.get("umbrales", bucket) if isinstance(bucket, dict) else bucket

    def reset_con_ticker(tabla: pd.DataFrame) -> pd.DataFrame:
        reset = tabla.reset_index()
        if "index" in reset.columns:
            reset = reset.rename(columns={"index": "ticker"})
        else:
            primera = reset.columns[0]
            if primera not in tabla.columns:
                reset = reset.rename(columns={primera: "ticker"})
        return reset

    # Si el nombre del segundo parámetro sugiere umbrales, probamos primero esa
    # variante; en caso contrario, probamos primero el bucket completo.
    segundo_parametro = ""
    try:
        parametros = list(inspect.signature(funcion).parameters)
        if len(parametros) > 1:
            segundo_parametro = parametros[1].lower()
    except Exception:
        pass

    prefiere_umbrales = any(
        token in segundo_parametro
        for token in ("umbral", "regla", "cond", "threshold")
    )

    pares_base: list[tuple[pd.DataFrame, Any]] = [
        (tabla_norm, umbrales if prefiere_umbrales else bucket),
        (tabla_norm, bucket if prefiere_umbrales else umbrales),
        (tabla_cruda, umbrales if prefiere_umbrales else bucket),
        (tabla_cruda, bucket if prefiere_umbrales else umbrales),
        (reset_con_ticker(tabla_norm), umbrales if prefiere_umbrales else bucket),
        (reset_con_ticker(tabla_norm), bucket if prefiere_umbrales else umbrales),
        (reset_con_ticker(tabla_cruda), umbrales if prefiere_umbrales else bucket),
        (reset_con_ticker(tabla_cruda), bucket if prefiere_umbrales else umbrales),
    ]

    candidatos = [(tabla, parametro) for tabla, parametro in pares_base]
    resultado = _llamar_seleccion(funcion, candidatos)

    if resultado is None:
        return _aplicar_bucket_manual(tabla_norm, bucket)

    return resultado


def _valor_en_fecha(serie: pd.Series, fecha: pd.Timestamp) -> float:
    try:
        valor = serie.loc[fecha]
        if isinstance(valor, pd.Series):
            valor = valor.iloc[-1]
        if pd.isna(valor):
            return float("nan")
        return float(valor)
    except Exception:
        return float("nan")


def _valor_feature(
    features_simbolo: pd.DataFrame,
    fecha: pd.Timestamp,
    columna: str,
) -> float:
    try:
        fila = features_simbolo.loc[fecha]
        if isinstance(fila, pd.DataFrame):
            fila = fila.iloc[-1]
        if columna not in fila.index:
            return float("nan")
        valor = fila[columna]
        if pd.isna(valor):
            return float("nan")
        return float(valor)
    except Exception:
        return float("nan")


def _signal_dict(
    fecha: pd.Timestamp,
    ticker: str,
    datos_simbolo: dict[str, Any],
    incluir_vol: bool,
) -> dict[str, Any]:
    señal: dict[str, Any] = {
        "fecha": fecha,
        "ticker": ticker,
    }

    for horizonte in _HORIZONTES:
        señal[f"retorno_{horizonte}d"] = _valor_en_fecha(
            datos_simbolo["retornos"][horizonte], fecha
        )

    if incluir_vol:
        señal["vol_realizada_20d_cruda"] = _valor_feature(
            datos_simbolo["features"],
            fecha,
            "vol_realizada_20d_cruda",
        )

    return señal


def construir_senales_para_fechas(
    inputs_dir: Path,
    universo_path: Path,
    fechas: list[pd.Timestamp],
    bucket_congelado: dict,
    benchmark: str = "SPY",
    min_historia: int = 252,
) -> dict[str, pd.DataFrame]:
    """Ejecuta el bucket congelado y los baselines sobre fechas ya dadas.

    Esta función no descubre fechas ni selecciona parámetros: sólo aplica una
    regla fija sobre las fechas de corte recibidas.
    """
    inputs_dir = Path(inputs_dir)
    universo_path = Path(universo_path)

    universo = _leer_universo(universo_path)

    simbolos_a_cargar: list[str] = []
    vistos: set[str] = set()
    for simbolo in [*universo, benchmark]:
        if simbolo not in vistos:
            simbolos_a_cargar.append(simbolo)
            vistos.add(simbolo)

    datos: dict[str, dict[str, Any]] = {}

    for simbolo in simbolos_a_cargar:
        precios = _leer_parquet(inputs_dir / f"{simbolo}.parquet")
        if precios is None:
            continue

        precios_ajustados = _ajustar_ohlc_seguro(precios)
        cierre = _serie_cierre(precios_ajustados)
        features_simbolo = _calcular_features_seguro(precios_ajustados)

        retornos = {
            horizonte: retorno_forward(cierre, horizonte)
            for horizonte in _HORIZONTES
        }

        datos[simbolo] = {
            "precios": precios,
            "precios_ajustados": precios_ajustados,
            "cierre": cierre,
            "features": features_simbolo,
            "retornos": retornos,
        }

    filas_por_metodo: dict[str, list[dict[str, Any]]] = {
        "ganador": [],
        "baseline_momentum_simple": [],
        "baseline_buy_hold": [],
        "baseline_rsi_simple": [],
        "baseline_combo_ingenuo": [],
        "spy": [],
    }

    for fecha in fechas:
        filas_cross_section: dict[str, pd.Series] = {}
        elegibles: list[str] = []

        for simbolo in universo:
            if simbolo not in datos:
                continue

            info = datos[simbolo]
            precios = info["precios"]
            features_simbolo = info["features"]

            if fecha not in features_simbolo.index:
                continue

            if len(precios.loc[:fecha]) < min_historia:
                continue

            fila_features = features_simbolo.loc[fecha]
            if isinstance(fila_features, pd.DataFrame):
                fila_features = fila_features.iloc[-1]

            if fila_features.isna().any():
                continue

            filas_cross_section[simbolo] = fila_features
            elegibles.append(simbolo)

        if not filas_cross_section:
            continue

        tabla_cruda = pd.DataFrame.from_dict(
            filas_cross_section,
            orient="index",
        )
        tabla_cruda.index.name = "ticker"

        tabla_norm = _normalizar_seguro(tabla_cruda)

        # Bucket congelado -> "ganador".
        resultado_bucket = _seleccionar_bucket(
            tabla_norm,
            tabla_cruda,
            bucket_congelado,
        )
        tickers_ganador = _extraer_tickers(resultado_bucket, tabla_norm)
        for ticker in dict.fromkeys(tickers_ganador):
            if ticker in filas_cross_section and ticker in datos:
                filas_por_metodo["ganador"].append(
                    _signal_dict(fecha, ticker, datos[ticker], incluir_vol=True)
                )

        # Baseline momentum simple.
        resultado_momentum = _llamar_seleccion(
            baselines.baseline_momentum_simple,
            [
                (tabla_norm,),
                (tabla_cruda,),
                (tabla_norm, "mom_20d"),
                (tabla_cruda, "mom_20d"),
            ],
        )
        tickers_momentum = _extraer_tickers(resultado_momentum, tabla_norm)
        for ticker in dict.fromkeys(tickers_momentum):
            if ticker in filas_cross_section and ticker in datos:
                filas_por_metodo["baseline_momentum_simple"].append(
                    _signal_dict(fecha, ticker, datos[ticker], incluir_vol=True)
                )

        # Baseline buy & hold sobre la lista de elegibles.
        resultado_buy_hold = _llamar_seleccion(
            baselines.baseline_buy_hold,
            [
                (elegibles,),
                (tabla_cruda, elegibles),
                (elegibles, tabla_cruda),
                (tabla_cruda,),
            ],
        )
        tickers_buy_hold = _extraer_tickers(resultado_buy_hold, tabla_norm)
        for ticker in dict.fromkeys(tickers_buy_hold):
            if ticker in filas_cross_section and ticker in datos:
                filas_por_metodo["baseline_buy_hold"].append(
                    _signal_dict(fecha, ticker, datos[ticker], incluir_vol=True)
                )

        # Baseline RSI simple.
        resultado_rsi = _llamar_seleccion(
            baselines.baseline_rsi_simple,
            [
                (tabla_norm,),
                (tabla_cruda,),
                (tabla_norm, "rsi_14"),
                (tabla_cruda, "rsi_14"),
                (tabla_norm, "rsi"),
                (tabla_cruda, "rsi"),
            ],
        )
        tickers_rsi = _extraer_tickers(resultado_rsi, tabla_norm)
        for ticker in dict.fromkeys(tickers_rsi):
            if ticker in filas_cross_section and ticker in datos:
                filas_por_metodo["baseline_rsi_simple"].append(
                    _signal_dict(fecha, ticker, datos[ticker], incluir_vol=True)
                )

        # Baseline combo ingenuo, sobre features crudas.
        resultado_combo = _llamar_seleccion(
            baselines.baseline_combo_ingenuo,
            [
                (tabla_cruda,),
                (tabla_norm,),
                (tabla_cruda, "mom_20d", "rsi_14"),
                (tabla_cruda, "rsi_14", "mom_20d"),
            ],
        )
        tickers_combo = _extraer_tickers(resultado_combo, tabla_norm)
        for ticker in dict.fromkeys(tickers_combo):
            if ticker in filas_cross_section and ticker in datos:
                filas_por_metodo["baseline_combo_ingenuo"].append(
                    _signal_dict(fecha, ticker, datos[ticker], incluir_vol=True)
                )

        # Benchmark: una única señal por fecha, sin filtro de elegibilidad.
        if benchmark in datos:
            info_benchmark = datos[benchmark]
            if fecha in info_benchmark["retornos"][30].index:
                filas_por_metodo["spy"].append(
                    _signal_dict(fecha, benchmark, info_benchmark, incluir_vol=False)
                )

    resultado_final: dict[str, pd.DataFrame] = {}

    for metodo, filas in filas_por_metodo.items():
        columnas = _COLUMNAS_SPY if metodo == "spy" else _COLUMNAS_SENAL
        if filas:
            df = pd.DataFrame(filas)
            df = df.reindex(columns=columnas)
        else:
            df = pd.DataFrame(columns=columnas)
        resultado_final[metodo] = df

    return resultado_final
